func:
// ONE place to describe every value coming from the PLC.
// key: 'coils/<NAME>' for the coils (names as in modbus2mqtt/config.yaml),
//      'analog/in1' / 'analog/in2' for the holding registers.
// invert: true for NC contacts (PLC bit is 1 when NOT pressed).
// Analog: shown value = raw * scale + offset  -> set scale/offset/unit once you know the signal.
const B = (key, label, group, onText = 'ON', offText = 'OFF', alarmWhenOn = false, invert = false) =>
    ({ key, label, group, type: 'bool', onText, offText, alarmWhenOn, invert });
const N = (key, label, group, unit = '', scale = 1, offset = 0, decimals = 0) =>
    ({ key, label, group, type: 'num', unit, scale, offset, decimals });

const tags = [
    B('coils/B1', 'Sensor B1', 'Sensors', 'DETECT', 'clear'),
    B('coils/B2', 'Sensor B2', 'Sensors', 'DETECT', 'clear'),
    B('coils/B3', 'Sensor B3', 'Sensors', 'DETECT', 'clear'),
    B('coils/B4', 'Sensor B4 (metal)', 'Sensors', 'METAL', 'clear'),

    N('analog/in1', 'Analog input 1', 'Analog'),          // e.g. N('analog/in1','RTD 1','Analog','°C',0.1,0,1)
    N('analog/in2', 'Analog input 2', 'Analog'),

    B('coils/ES0', 'E-stop', 'Operator panel', 'PRESSED', 'ok', true, true),       // NC: 1 = safe
    B('coils/MODE_AUTO_MAN', 'Auto / Manual', 'Operator panel', 'AUTO', 'MANUAL'), // verify which state is AUTO
    B('coils/MODE_DG_OEE', 'DG / OEE', 'Operator panel', 'OEE', 'DG'),             // verify which state is OEE
    B('coils/PB_GREEN', 'Green button', 'Operator panel', 'pressed', '-'),
    B('coils/PB_YELLOW', 'Yellow button', 'Operator panel', 'pressed', '-'),
    B('coils/PB_RED', 'Red button', 'Operator panel', 'pressed', '-', false, true), // rests TRUE
    B('coils/LED_GREEN', 'Panel LED green', 'Operator panel'),
    B('coils/LED_YELLOW', 'Panel LED yellow', 'Operator panel'),
    B('coils/LED_RED', 'Panel LED red', 'Operator panel', 'ON', 'OFF', true),

    B('coils/TL_3_G', 'Tower light green', 'Tower light'),
    B('coils/TL_2_Y', 'Tower light yellow', 'Tower light'),
    B('coils/TL_1_R', 'Tower light red', 'Tower light', 'ON', 'OFF', true),

    B('coils/K1_R1', 'Relay K1 + R1', 'Relays'),
    B('coils/K2', 'Relay K2', 'Relays'),
    B('coils/R2', 'Relay R2', 'Relays'),
    B('coils/K3', 'Relay K3', 'Relays'),
];
// TagoIO variable name: lowercase letters, digits, underscore  (coils/B1 -> b1, analog/in1 -> analog_in1)
for (const t of tags) t.tago = t.key.replace(/^coils\//, '').replace(/[^a-z0-9]/gi, '_').toLowerCase();
flow.set('tags', tags);

// Show everything on first run, and add any newly defined tag to an existing selection
const sel = global.get('selected');
if (!Array.isArray(sel)) {
    global.set('selected', tags.map(t => t.key));
} else {
    const prev = global.get('allKeys') || [];
    const added = tags.map(t => t.key).filter(k => !prev.includes(k) && !sel.includes(k));
    if (added.length && prev.length) global.set('selected', sel.concat(added));
}
global.set('allKeys', tags.map(t => t.key));
return msg;

// Keep the latest value of every data point in flow context.
const topic = msg.topic.replace(/^station\/nx1p2\//, '');
const raw = String(msg.payload).trim();
const latest = flow.get('latest') || {};
const now = Date.now();
const out = [];

if (topic === 'online') {                       // connection state from (patched) modbus2mqtt
    flow.set('online', raw === 'true');
    flow.set('onlineAt', now);
    return null;
}

// ESP32_GUI web server: one topic per register, e.g. station/nx1p2/es0 = "1", station/nx1p2/analog_in1 = "302"
const perReg = (flow.get('tags') || []).find(x => x.tago === topic.toLowerCase());
if (perReg) {
    const num = Number(raw);
    latest[perReg.key] = { v: isNaN(num) ? raw : num, ts: now };
    flow.set('regAt', now);                     // the gateway only publishes values it read OK -> PLC online
    if (perReg.type !== 'bool' && !isNaN(num))
        out.push({ topic: perReg.label, payload: Number((num * perReg.scale + perReg.offset).toFixed(perReg.decimals)) });
} else if (topic === 'coils') {                 // {"ES0":1,"B1":0,...} -> coils/ES0, coils/B1 ...
    let obj;
    try { obj = JSON.parse(raw); } catch (e) { node.warn('bad coils JSON: ' + raw); return null; }
    for (const [name, v] of Object.entries(obj)) latest['coils/' + name] = { v: Number(v), ts: now };
} else {
    const num = Number(raw);
    latest[topic] = { v: (raw !== '' && !isNaN(num)) ? num : raw, ts: now };
    // scaled value to the trend chart (skipped until 'Define tags' has run, so series names stay consistent)
    const t = topic.startsWith('analog/') && (flow.get('tags') || []).find(x => x.key === topic);
    if (t && !isNaN(num)) {
        out.push({ topic: t.label, payload: Number((num * t.scale + t.offset).toFixed(t.decimals)) });
    }
}
flow.set('latest', latest);
flow.set('lastDataAt', now);
return out.length ? [out] : null;

// Builds the tile list for the Main page from the selected values.
const tags = flow.get('tags') || [];
const latest = flow.get('latest') || {};
const selected = global.get('selected') || [];
const online = flow.get('online') === true || Date.now() - (flow.get('regAt') || 0) < 5000;
const hasData = Object.keys(latest).length > 0;

const tiles = tags.filter(t => selected.includes(t.key)).map(t => {
    const d = latest[t.key];
    if (!d) return { key: t.key, label: t.label, text: '—', cls: 'nodata' };
    if (t.type === 'bool') {
        const on = (Number(d.v) === 1) !== t.invert;
        return { key: t.key, label: t.label, text: on ? t.onText : t.offText,
                 cls: on ? (t.alarmWhenOn ? 'alarm' : 'on') : 'off' };
    }
    const v = Number(d.v) * t.scale + t.offset;
    return { key: t.key, label: t.label, text: v.toFixed(t.decimals) + (t.unit ? ' ' + t.unit : ''), cls: 'num' };
});

const lastAt = flow.get('lastDataAt') || 0;
const updated = lastAt ? 'last change ' + new Date(lastAt).toLocaleTimeString('en-GB', { timeZone: 'Asia/Kuala_Lumpur' }) : '';
const status = online ? 'PLC online' : (hasData ? 'PLC offline - showing last known values' : 'Waiting for data from the gateway…');

const sig = JSON.stringify([online, status, tiles, updated]);
if (sig === context.get('lastSig')) return null;   // nothing changed -> don't resend
context.set('lastSig', sig);

node.status({ fill: online ? 'green' : 'red', shape: 'dot', text: status });
return { payload: { online, status, tiles, updated } };

// Sends the list of available values + current selection to the Settings page.
const tags = flow.get('tags') || [];
const groups = [];
for (const t of tags) {
    let g = groups.find(x => x.name === t.group);
    if (!g) { g = { name: t.group, items: [] }; groups.push(g); }
    g.items.push({ key: t.key, label: t.label });
}
return { payload: { groups, selected: global.get('selected') || [], saved: msg.saved === true } };

// Called when the user presses Save on the Settings page.
const tags = (flow.get('tags') || []).map(t => t.key);
const sel = Array.isArray(msg.payload) ? msg.payload.filter(k => tags.includes(k)) : [];
global.set('selected', sel);          // persisted to disk (contextStorage in settings.js)
node.status({ fill: 'blue', shape: 'dot', text: sel.length + ' values selected' });
return { saved: true };

// Sends values to TagoIO over HTTP (TagoIO's own MQTT broker is not on the free plan).
// Only values that changed since the last push are sent, plus everything every 5 min,
// to stay inside the free plan's data limits.
const token = env.get('TAGO_DEVICE_TOKEN');
if (!token || token.startsWith('PASTE')) { node.status({ fill: 'yellow', shape: 'ring', text: 'set TAGO_DEVICE_TOKEN' }); return null; }

const online = flow.get('online') === true || Date.now() - (flow.get('regAt') || 0) < 5000;
const tags = flow.get('tags') || [];
const latest = flow.get('latest') || {};
const sent = context.get('sent') || {};
const analogDue = Date.now() - (context.get('lastAnalog') || 0) >= 10000;   // analog values change all the time: max every 10 s
const fullDue = Date.now() - (context.get('lastFull') || 0) > 5 * 60 * 1000;

const data = [];
if (context.get('sentOnline') !== online || fullDue) {
    data.push({ variable: 'plc_online', value: online });
    context.set('sentOnline', online);
}
if (online) {
    for (const t of tags) {
        const d = latest[t.key];
        if (!d) continue;
        if (!fullDue && sent[t.key] === d.v) continue;
        if (!fullDue && t.type !== 'bool' && !analogDue) continue;
        let value;
        if (t.type === 'bool') value = ((Number(d.v) === 1) !== t.invert) ? 1 : 0;   // 1 = "on" meaning (e.g. e-stop pressed)
        else value = Number((Number(d.v) * t.scale + t.offset).toFixed(t.decimals));
        const item = { variable: t.tago, value };
        if (t.unit) item.unit = t.unit;
        data.push(item);
        sent[t.key] = d.v;
    }
    if (fullDue) context.set('lastFull', Date.now());
    if (data.some(x => tags.find(t => t.tago === x.variable && t.type !== 'bool'))) context.set('lastAnalog', Date.now());
    context.set('sent', sent);
}
if (!data.length) { node.status({ fill: 'grey', shape: 'dot', text: online ? 'no changes' : 'PLC offline' }); return null; }

node.status({ fill: 'blue', shape: 'dot', text: 'sending ' + data.length + ' values' });
return {
    url: env.get('TAGO_URL') || 'https://api.tago.io/data',
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Device-Token': token },
    payload: data
};

const ok = msg.statusCode >= 200 && msg.statusCode < 300;
node.status({ fill: ok ? 'green' : 'red', shape: 'dot',
              text: (ok ? 'TagoIO OK ' : 'TagoIO error ') + msg.statusCode + ' @ ' + new Date().toLocaleTimeString('en-GB') });
return ok ? null : msg;   // errors go to the debug sidebar
